css='''*{box-sizing:border-box}:root{color-scheme:dark}body{margin:0;background:#171a15;color:#e7e3da;font:16px/1.5 Arial,Helvetica,sans-serif}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}button,a{cursor:pointer}button{color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #d4dfbc;outline-offset:3px}a{color:#e7e3da;text-underline-offset:4px}.review-header{max-width:1080px;margin:0 auto;padding:32px 24px 20px}.review-header h1{font-size:clamp(28px,4.8vw,46px);line-height:1.08;margin:10px 0 16px;max-width:760px}.review-header p{max-width:760px;color:#c3c7b9}.review-header .eyebrow{color:#d1dac2}.layout{max-width:1080px;padding:0 24px 64px;margin:auto;display:grid;grid-template-columns:minmax(220px,300px) minmax(0,480px);gap:48px;align-items:start}.review{position:sticky;top:20px}.review>details{border-top:1px solid #626b58;padding:16px 0}.review summary{font-size:18px;font-weight:700;cursor:pointer;min-height:38px}.review button{display:block;width:100%;padding:11px 14px;margin:8px 0;text-align:left;border:1px solid #748062;border-radius:8px;background:#23291e;min-height:44px}.review .small{color:#c3c7b9;font-size:14px}.review ul{padding-left:20px}.review label{display:block}.review select{margin:8px 0;width:100%;padding:10px;border:1px solid #748062;border-radius:7px;background:#11170c;color:#e7e3da}.phone{background:#050505;border:1px solid #707762;border-radius:25px;overflow:clip;min-width:0;box-shadow:0 20px 70px #0005}.app-header{display:flex;gap:9px;align-items:center;padding:17px 18px;border-bottom:1px solid #484b40;min-height:72px}.app-header img{width:30px;height:30px;object-fit:contain}.app-header strong{font-size:16px;letter-spacing:.18em}.app-header button{margin-left:auto;border:0;background:none;padding:6px 4px;font-size:27px;min-width:44px;min-height:44px}.example-ribbon{font-size:11px;letter-spacing:.08em;background:#21251c;color:#d8dfcd;padding:8px 18px;text-transform:uppercase}.hero{position:relative;overflow:hidden;background:linear-gradient(110deg,#3b4331,#535d46);padding:24px 20px 26px;isolation:isolate}.hero:after{content:'';position:absolute;width:1px;right:40px;top:-30px;height:calc(100% + 60px);background:#b3baa3;transform:rotate(24deg);z-index:-1}.hero h1{font-size:34px;line-height:1.11;letter-spacing:-.035em;max-width:350px;margin:10px 60px 16px 0;text-wrap:balance}.hero>p:last-child{margin-bottom:0;max-width:calc(100% - 70px);margin-top:18px}.eyebrow{font-size:11px;letter-spacing:.17em;font-weight:700;text-transform:uppercase;color:#d0d9ba;margin:0 0 12px}.content{padding:18px 18px 26px}.card{padding:19px;border:1px solid #484b40;border-radius:13px;background:#10120f;margin:18px 0}.card h2{font-size:24px;line-height:1.15;letter-spacing:-.025em;margin:0 0 13px}.card h3{font-size:18px;line-height:1.25;margin:14px 0 9px}.card p:last-child{margin-bottom:0}.card p{margin:12px 0}.prepared{border-color:#777f68}.primary,.secondary{display:flex;align-items:center;justify-content:center;gap:16px;min-height:48px;width:100%;padding:12px 15px;border-radius:8px;text-decoration:none;font-weight:700;border:1px solid #707762;margin:12px 0}.primary{background:#707762;color:#fff}.secondary{background:#11150e;color:#e7e3da}.primary span{margin-left:auto;font-size:24px}.meta{font-size:13px;color:#c3c7b9;line-height:1.5}.reason{border-left:2px solid #707762;padding-left:12px;color:#dce0d3}.fallback{font-size:14px;color:#d2d7c8}.choice{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:60px;width:100%;text-align:left;background:#10120f;border:1px solid #484b40;border-radius:9px;padding:14px;margin:12px 0}.choice span{font-size:24px}.feelings{margin:0 0 24px}.feelings h2{margin-bottom:10px}.feelings>div{display:flex;gap:8px}.chip{flex:1;background:#10120f;border:1px solid #5a624f;border-radius:7px;padding:10px 3px;min-height:43px;font-size:14px}.chip.selected{background:#c9dab0;color:#080a06}.text-actions{display:flex;gap:20px;flex-wrap:wrap;margin-top:16px}.text-actions button,.text-link{padding:3px 0;border:0;background:none;text-decoration:underline;text-underline-offset:4px;min-height:40px;font-size:14px}.masked{filter:blur(9px);user-select:none}.reveal{position:absolute;left:20px;top:66px;max-width:calc(100% - 40px);border:1px solid #e7e3da;background:#10120fee;padding:11px 15px;border-radius:8px;font-size:15px}.notice{padding:12px 14px;background:#242b1d;border-radius:8px;border-left:2px solid #b5c49e}.feedback-options{display:grid;gap:8px}.feedback-options button,.clarifier button{padding:11px 13px;border:1px solid #626b55;border-radius:7px;background:#161b12;text-align:left;min-height:45px}.clarifier{display:grid;gap:8px;padding-top:12px;margin-top:12px;border-top:1px solid #484b40}.safety{color:#c3c7b9;font-size:13px;margin:24px 0 4px}.row{text-decoration:none;width:100%;display:flex;align-items:center;justify-content:space-between;gap:15px;padding:17px;border:1px solid #484b40;border-radius:11px;background:#10120f;text-align:left;margin:12px 0}.row strong{font-size:19px}.row small{display:block;color:#c3c7b9;font-size:14px;margin-top:5px}.row>span:last-child{font-size:27px}.row>span{min-width:0}.continuity{background:#20271b}.warm,.win{border-top:1px solid #707762;margin:24px 0;padding-top:18px}.win h2{font-size:25px;line-height:1.2;margin:10px 0}.latest{font-size:30px;font-weight:700}.latest small{font-size:13px;display:block;color:#c3c7b9;font-weight:400}.chart svg{width:100%;height:auto}.chart text{font:17px Arial;fill:#c3c7b9}.chart-controls{display:grid;grid-template-columns:1fr 1fr;gap:12px}.chart-controls label,.select-label,.edit label{display:block;font-size:14px}.content select,.edit select{display:block;margin:6px 0 14px;width:100%;min-height:44px;background:#12170e;color:#e7e3da;border:1px solid #707762;padding:9px;border-radius:6px}.card li{margin:12px 0}.card ul,.card ol{padding-left:22px}summary{cursor:pointer;min-height:44px;padding:9px 0}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:8px;border-bottom:1px solid #484b40}.check{display:flex;align-items:center;gap:10px}.check input{width:22px;height:22px}.urgent{border-color:#aab995}.urgent a{font-size:14px;line-height:1.4}.phone>footer{font-size:11px;color:#c3c7b9;padding:10px 18px;border-top:1px solid #484b40}.nav{position:sticky;bottom:0;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0;padding:9px 3px 12px;border-top:1px solid #5c6451;background:#050505;z-index:4}.nav[hidden]{display:none}.nav button{display:flex;flex-direction:column;align-items:center;gap:5px;border:0;background:none;color:#b5b8ad;min-width:0;min-height:57px;font-size:11px;position:relative;padding:4px 0 10px}.nav svg{width:23px;height:23px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.nav [aria-current=page]{color:#f0ece4;font-weight:700}.nav [aria-current=page]:after{content:'';position:absolute;bottom:0;width:18px;height:3px;background:#e7e3da;border-radius:2px}dialog{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);margin:0;background:#10150d;color:#e7e3da;border:1px solid #909d7c;border-radius:15px;padding:23px;width:min(430px,calc(100vw - 24px));max-height:85vh;overflow:auto;z-index:40;box-shadow:0 0 0 100vmax #000c}dialog h2{font-size:27px;line-height:1.15;margin:0 0 16px}dialog label{display:block;margin:14px 0}dialog select,dialog textarea{display:block;width:100%;padding:10px;margin:8px 0;background:#080b05;color:#e7e3da;border:1px solid #707762;border-radius:6px}dialog article{border-bottom:1px solid #58604b;padding:10px 0}dialog li{margin:9px 0}.menu{position:fixed;inset:8vh max(12px,calc((100vw - 450px)/2));background:#10150d;border:1px solid #707762;border-radius:14px;padding:20px;overflow:auto;z-index:30;box-shadow:0 0 0 100vmax #000c}.menu h2{display:inline-block;margin:0}.menu>.secondary{position:sticky;top:0;background:#e7e3da;color:#050505}.menu .row{padding:9px 12px;margin:8px 0}.menu .row small{display:none}.menu .row strong{font-size:17px}@media(max-width:760px){.review-header{padding:23px 16px 10px}.review-header h1{font-size:31px}.layout{display:flex;flex-direction:column;gap:18px;padding:0 0 30px}.review{position:static;padding:0 16px;width:100%}.review>details:not(:first-child){display:none}.phone{width:100%;border-radius:0;border-left:0;border-right:0;box-shadow:none}.phone .hero h1{font-size:33px}.review>details:first-child{padding:10px 0}.review .state-buttons{display:grid;grid-template-columns:1fr 1fr;gap:6px}.review .state-buttons button{margin:0;font-size:13px}.review label{font-size:13px}.review-header p{font-size:14px}}@media print{.review,.review-header{display:none}.layout{display:block;padding:0;max-width:480px}.phone{border:0;box-shadow:none}.nav{position:static}body{background:#050505}.card{break-inside:avoid}}'''
html='''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Timber · Try something useful, then return</title><style>'''+css+'''</style></head><body><header class="review-header"><p class="eyebrow">PRIVATE PRODUCT PREVIEW · ALL PEOPLE AND DATA ARE FICTIONAL</p><h1>A useful first visit.<br>A reason to return.</h1><p>A working example of the proposed experience. It makes no live service claim, creates no account and contacts nobody. The feedback and memory below are stored only in this browser.</p></header><div class="layout"><aside class="review"><details open><summary>Try the journey</summary><div class="state-buttons"><button data-action="first">1 · First useful visit</button><button data-action="day2">2 · Return on day two</button><button data-action="day30">3 · Load fictional day thirty</button><button data-action="return">4 · Return after quiet days</button><button data-action="change">5 · Treatment situation changes</button></div><label>Fictional account<select id="person"><option value="dan">Dan</option><option value="lee">Lee · separate example history</option></select></label><p id="exampleStatus" class="small"></p></details><details open><summary>What to test</summary><ul><li>Choose a difficulty and get something ready to use.</li><li>Preview joining, then answer “Did it help?”</li><li>Use “Not for me” to change timing, effort or the idea.</li><li>Refresh: this fictional account keeps its answers.</li><li>Switch accounts: histories stay separate.</li></ul><p id="evidenceSummary" class="small"></p></details><details open><summary>What this proves</summary><p class="small">The proposed interface and deterministic example work together. It does not prove live AI preparation, cross-device storage, clinical outcomes or independent human usefulness.</p><p class="small">The five graph examples reuse the agreed invented records. They are not expected results.</p></details></aside><article class="phone"><header class="app-header"><img src="data:image/png;base64,'''+badge+'''" alt="SHIFT"><strong>MY TIMBER</strong><button type="button" data-action="menu" aria-label="Open menu">☰</button></header><div class="example-ribbon" id="joinedStatus"></div><main id="screen"></main><footer>Illustrative example · private preview only · no live account changes</footer><nav class="nav" id="nav" aria-label="My Timber example pages"></nav></article></div><div id="menu"></div><div id="modal"></div><script>'''+model+'\nconst theory='+json.dumps(data,ensure_ascii=False).replace('</','<\\/')+';\n'+view+'''</script></body></html>'''
out=ROOT/'My-Timber-Try-and-Return.html';out.write_text(html);print(out,len(html))
